/**
 * Turns the widget example screenshots into the images the tool pages show.
 *
 *   _img/examples/<id>.png             full-size screenshot (not committed - regenerated by
 *                                      MappiaExplorer's `npm run docs:screenshots`)
 *   _img/examples/<id>.crop.json       the part of it to keep (the panel, the dialogs and the map
 *                                      area of the example's effect), written by the same run
 *   assets/img/examples/<id>.jpg       up to 1600 px, shown when the picture is opened
 *   assets/img/examples/<id>_thumb.jpg  800 px, shown on the tool page and its card
 *
 * The site only shows a picture whose .jpg exists, so a screenshot is published by running
 * this script and unpublished by deleting its two .jpg files. Nothing is ever deleted here:
 * the .png folder is not committed, so on a fresh checkout it is empty and must not take the
 * published pictures with it.
 *
 * gulp-responsive (the site's usual image pipeline) needs Node 14; this uses the image codecs
 * Windows already has, through ONE PowerShell process for the whole batch.
 *
 * Usage: node script/example-images.js [--force]   (--force re-encodes up-to-date images)
 */

const fs = require("fs");
const os = require("os");
const path = require("path");
const { spawnSync } = require("child_process");

const SITE_ROOT = path.join(__dirname, "..");
const SOURCE_DIR = path.join(SITE_ROOT, "_img", "examples");
const TARGET_DIR = path.join(SITE_ROOT, "assets", "img", "examples");
const SIZES = [
    { suffix: "", width: 1600 },
    { suffix: "_thumb", width: 800 },
];
const JPEG_QUALITY = 85;

const POWERSHELL_SCRIPT = String.raw`
param([string]$JobsFile, [int]$Quality)
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing
$codec = [System.Drawing.Imaging.ImageCodecInfo]::GetImageEncoders() | Where-Object { $_.MimeType -eq 'image/jpeg' }
$encoderParams = New-Object System.Drawing.Imaging.EncoderParameters 1
$encoderParams.Param[0] = New-Object System.Drawing.Imaging.EncoderParameter ([System.Drawing.Imaging.Encoder]::Quality, [long]$Quality)
$jobs = Get-Content -Raw -Path $JobsFile | ConvertFrom-Json
foreach ($job in $jobs) {
    $source = [System.Drawing.Image]::FromFile($job.source)
    try {
        # The crop is given in CSS pixels of the page; the screenshot may be at 2x density.
        $area = New-Object System.Drawing.Rectangle 0, 0, $source.Width, $source.Height
        if ($job.crop) {
            $scale = $source.Width / $job.crop.viewportWidth
            $area = New-Object System.Drawing.Rectangle ([int]($job.crop.x * $scale)), ([int]($job.crop.y * $scale)), ([int]($job.crop.width * $scale)), ([int]($job.crop.height * $scale))
        }
        foreach ($output in $job.outputs) {
            $width = [Math]::Min($output.width, $area.Width) # never enlarge past what was captured
            $height = [int][Math]::Round($area.Height * $width / $area.Width)
            $bitmap = New-Object System.Drawing.Bitmap $width, $height
            $graphics = [System.Drawing.Graphics]::FromImage($bitmap)
            $graphics.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
            $graphics.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
            $graphics.DrawImage($source, (New-Object System.Drawing.Rectangle 0, 0, $width, $height), $area, [System.Drawing.GraphicsUnit]::Pixel)
            $bitmap.Save($output.path, $codec, $encoderParams)
            $graphics.Dispose()
            $bitmap.Dispose()
        }
    } finally {
        $source.Dispose()
    }
    Write-Output ("  " + [System.IO.Path]::GetFileName($job.source))
}
`;

function isUpToDate(source, target) {
    return fs.existsSync(target) && fs.statSync(target).mtimeMs >= fs.statSync(source).mtimeMs;
}

function main() {
    const force = process.argv.includes("--force");
    if (!fs.existsSync(SOURCE_DIR)) {
        console.log(`No screenshots in ${path.relative(SITE_ROOT, SOURCE_DIR)} - run MappiaExplorer's "npm run docs:screenshots" first.`);
        return;
    }
    fs.mkdirSync(TARGET_DIR, { recursive: true });

    const jobs = fs.readdirSync(SOURCE_DIR)
        .filter((name) => name.toLowerCase().endsWith(".png"))
        .map((name) => {
            const source = path.join(SOURCE_DIR, name);
            const id = name.replace(/\.png$/i, "");
            // <id>.crop.json, written by the screenshot runner: the part of the page to keep.
            const cropFile = path.join(SOURCE_DIR, `${id}.crop.json`);
            const crop = fs.existsSync(cropFile) ? JSON.parse(fs.readFileSync(cropFile, "utf8")) : null;
            const outputs = SIZES
                .map((size) => ({ path: path.join(TARGET_DIR, `${id}${size.suffix}.jpg`), width: size.width }))
                .filter((output) => force || !isUpToDate(source, output.path) || (crop && !isUpToDate(cropFile, output.path)));
            return { source, crop, outputs };
        })
        .filter((job) => job.outputs.length > 0);

    if (jobs.length === 0) {
        console.log("Every example image is up to date.");
        return;
    }
    if (process.platform !== "win32") {
        console.error("This script encodes with the Windows image codecs; run it on Windows (or use gulp on Node 14).");
        process.exitCode = 1;
        return;
    }

    const workDir = fs.mkdtempSync(path.join(os.tmpdir(), "example-images-"));
    try {
        const scriptFile = path.join(workDir, "encode.ps1");
        const jobsFile = path.join(workDir, "jobs.json");
        fs.writeFileSync(scriptFile, POWERSHELL_SCRIPT);
        fs.writeFileSync(jobsFile, JSON.stringify(jobs));
        console.log(`Encoding ${jobs.length} screenshot(s) into ${path.relative(SITE_ROOT, TARGET_DIR)}:`);
        const result = spawnSync("powershell.exe",
            ["-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", scriptFile, "-JobsFile", jobsFile, "-Quality", String(JPEG_QUALITY)],
            { stdio: "inherit", timeout: 5 * 60 * 1000 });
        if (result.error || result.status !== 0) {
            console.error(`Encoding failed${result.error ? `: ${result.error.message}` : ` (exit ${result.status})`}.`);
            process.exitCode = 1;
        }
    } finally {
        fs.rmSync(workDir, { recursive: true, force: true });
    }
}

main();
